const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE_KEY='crowns-of-the-sundering-v2';
let preferences;try{preferences=loadPreferences(localStorage);if(!localStorage.getItem('crowns-player-preferences-v1')&&matchMedia('(pointer:coarse)').matches)preferences.quality='balanced';}catch{preferences=loadPreferences(null);}
let modalReturnFocus=null,roomRequestPending=false,districtPlacement=null;
const activeFactions=()=>state.factions.map(f=>factionMeta(f.id));
