let state=createGame('gondor',42), selectedTileId=state.cities.find(c=>c.faction===state.player).tileId, selectedUnitId=null, tab='realm',chosenFaction='gondor',moveMode=false,labels=true,started=false,toastTimer,world;
const multiplayer=new FriendSession({onError:toast,onBusy:()=>{syncOrderControls();renderRoomBar();},onConnection:()=>{syncOrderControls();renderRoomBar();},onSnapshot:snap=>{
 const wasLobby=!started||!$('#welcome').hidden||$('#modal-body').dataset.roomPanel==='true';
 if(!snap.state){showFriends();renderRoomBar();return;}
 const previousUnit=selectedUnitId,previousTile=selectedTileId;state=snap.state;started=true;$('#game').inert=false;$('#welcome').hidden=true;
 selectedUnitId=state.units.some(u=>u.id===previousUnit&&u.faction===state.player)?previousUnit:null;selectedTileId=unit()?.tileId||state.tiles.find(t=>t.id===previousTile&&t.explored)?.id||ownCities()[0]?.tileId||ownUnits()[0]?.tileId||'0,0';
 if(snap.confirmedAction==='SET_PRODUCTION')districtPlacement=null;if(wasLobby){closeModal();world?.focus(selectedTileId);}else if(snap.confirmedAction&&$('#modal').open)closeModal();render();if(snap.confirmedAction)toast(snap.message||actionFeedback(snap.confirmedAction));else if(snap.message)toast(snap.message);if(state.winner)showVictory();
}});
const factionMeta=id=>FACTIONS.find(f=>f.id===id)||{id,name:id,color:'#d4b573'};
const own=()=>getFaction(state,state.player);
const ownCities=()=>state.cities.filter(c=>c.faction===state.player);
const ownUnits=()=>state.units.filter(u=>u.faction===state.player);
