let audioCtx=null,musicOn=false,musicTimer;
function tone(frequency,duration=.25,volume=.02,type='sine'){if(!musicOn||!audioCtx)return;const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=frequency;gain.gain.setValueAtTime(0,audioCtx.currentTime);gain.gain.linearRampToValueAtTime(volume*preferences.volume,audioCtx.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration+.1);}
function playChord(){if(!musicOn)return;const chords=[[130.81,164.81,196,293.66],[110,146.83,174.61,261.63],[98,146.83,196,246.94],[130.81,174.61,220,329.63]];const chord=chords[Math.floor(Date.now()/6500)%4];chord.forEach((f,i)=>setTimeout(()=>tone(f,5,.008),i*170));musicTimer=setTimeout(playChord,6500);}
async function toggleMusic(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();musicOn=!musicOn;$('#sound').setAttribute('aria-pressed',String(musicOn));$('#sound').style.color=musicOn?'#e2c27d':'';clearTimeout(musicTimer);if(musicOn)playChord();toast(musicOn?'Ambient music enabled.':'Ambient music muted.');}
$('#sound').onclick=toggleMusic;

