document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.padCity){const c=state.cities.find(c=>c.id===d.padCity);selectedTileId=c.tileId;selectedUnitId=null;render();showProduction();}if(d.padUnit){const u=state.units.find(u=>u.id===d.padUnit);selectedUnitId=u.id;selectedTileId=u.tileId;world?.focus(u.tileId);render();closeModal();}if(d.padCouncil){modal(`<div class="eyebrow">THE COUNCIL</div><h2>Diplomacy</h2><div class="cards-grid">${activeFactions().filter(f=>f.id!==state.player).map(f=>`<div class="option-card"><h3>${esc(f.name)}</h3><p>${relation(f.id)==='war'?'At war':'At peace'}</p>${diplomacyActions(f.id)}</div>`).join('')}</div>`);}});
// Standard gamepad navigation; no vendor SDK or platform-specific binary required.
let padPrevious=[],padTime=0,cursorId=null;
function adjustPadSetting(el,direction){
 if(el.tagName==='SELECT'){el.selectedIndex=(el.selectedIndex+direction+el.options.length)%el.options.length;}
 else if(el.type==='checkbox')el.checked=!el.checked;
 else if(el.type==='range')el.value=String(Math.max(Number(el.min||0),Math.min(Number(el.max||100),Number(el.value)+direction*Number(el.step||1))));
 el.dispatchEvent(new Event('change',{bubbles:true}));
}
function pollPad(now){const pad=navigator.getGamepads?.()?.find(Boolean);if(pad){const pressed=i=>pad.buttons[i]?.pressed&&!padPrevious[i];const modalOpen=$('#modal').open||!$('#welcome').hidden;if(modalOpen){const scope=$('#modal').open?$('#modal'):$('#welcome'),buttons=[...scope.querySelectorAll('button:not(:disabled),summary,a[href],select,input[type=checkbox],input[type=range]')].filter(b=>!b.hidden&&b.getClientRects().length);let i=buttons.indexOf(document.activeElement);const current=document.activeElement,adjustable=current.matches('select,input[type=checkbox],input[type=range]');if(pressed(12)||(!adjustable&&pressed(14)))buttons[(i-1+buttons.length)%buttons.length]?.focus();if(pressed(13)||(!adjustable&&pressed(15)))buttons[(i+1)%buttons.length]?.focus();if(adjustable&&(pressed(14)||pressed(15)))adjustPadSetting(current,pressed(14)?-1:1);if(pressed(0)){if(buttons.includes(current)){if(adjustable)adjustPadSetting(current,1);else current.click();}else buttons[0]?.focus();}if(pressed(1)&&$('#modal').open)closeModal();}else if(started){if(now-padTime>170){let direction=null;if(pad.buttons[12]?.pressed)direction=[0,-1];if(pad.buttons[13]?.pressed)direction=[0,1];if(pad.buttons[14]?.pressed)direction=[-1,0];if(pad.buttons[15]?.pressed)direction=[1,0];if(Math.abs(pad.axes[0])>.5)direction=[Math.sign(pad.axes[0]),0];if(Math.abs(pad.axes[1])>.5)direction=[0,Math.sign(pad.axes[1])];if(direction){const t=getTile(state,cursorId||selectedTileId),id=`${t.q+direction[0]},${t.r+direction[1]}`;if(getTile(state,id)){cursorId=id;world?.focus(id);$('#hover-info').textContent=`Controller cursor · ${getTile(state,id).explored?terrainNames[getTile(state,id).terrain]:'Uncharted lands'} · A to select`;$('#hover-info').classList.add('show');}padTime=now;}}if(pressed(0))selectTile(cursorId||selectedTileId);if(pressed(1)){moveMode=false;selectedUnitId=null;render();}if(pressed(preferences.padBindings.nextUnit)){nextUnit();cursorId=selectedTileId;}if(pressed(preferences.padBindings.endTurn))requestEndTurn();if(pressed(preferences.padBindings.zoomOut))world?.zoom(-1);if(pressed(preferences.padBindings.zoomIn))world?.zoom(1);if(pressed(preferences.padBindings.rest)&&unit())action({type:'HEAL',unitId:selectedUnitId});if(pressed(preferences.padBindings.context)&&unit()){if(unit().kind==='hero')action({type:'HERO_POWER',unitId:selectedUnitId});else if(unit().kind==='settler')action({type:'FOUND_CITY',unitId:selectedUnitId});else if(unit().kind==='builder')showBuild();}if(pressed(preferences.padBindings.commands))showCommands();if(pressed(preferences.padBindings.menu))showMenu();}padPrevious=pad.buttons.map(b=>b.pressed);}else padPrevious=[];requestAnimationFrame(pollPad);}

try{world=new WorldView($('#world'),{onTileClick:id=>selectTile(typeof id==='string'?id:id?.id),onUnitClick:id=>{const u=state.units.find(x=>x.id===id);if(!u)return;if(u.faction===state.player){selectedUnitId=id;selectedTileId=u.tileId;moveMode=false;render();}else selectTile(u.tileId);},onTileHover:id=>{const t=getTile(state,typeof id==='string'?id:id?.id);if(!t){$('#hover-info').classList.remove('show');return;}const forecast=unit()?previewCombat(state,unit().id,t.id):null;$('#hover-info').textContent=forecast?.canAttack?`${forecast.targetName} · Deal ~${forecast.damage} damage · Receive ~${forecast.retaliation}`:t.explored?`${terrainNames[t.terrain]}${t.resource?' · '+t.resource:''}${t.visible&&t.owner?' · '+factionMeta(t.owner).name:''}`:'Uncharted lands';$('#hover-info').classList.add('show');}});}catch(err){console.error(err);$('#world').innerHTML='<div style="padding:130px 300px;color:#e9dfbd">The 3D world could not start. Please use a browser with WebGL 2 enabled.</div>';}
