function syncRoomControls(){document.querySelectorAll('[data-room-action]').forEach(button=>{if(['copy','return'].includes(button.dataset.roomAction))return;if(roomRequestPending&&!button.disabled){button.dataset.roomLocked='true';button.disabled=true;}else if(!roomRequestPending&&button.dataset.roomLocked){button.disabled=false;delete button.dataset.roomLocked;}});}
function initializeFriends(){
 document.querySelectorAll('[data-friends]').forEach(button=>button.onclick=showFriends);
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-room-action]');if(!button||button.disabled||roomRequestPending)return;const command=button.dataset.roomAction;roomRequestPending=true;syncRoomControls();const feedback=$('#friend-error');if(feedback)feedback.textContent=['copy','return'].includes(command)?'':'Connecting to your room…';
  try{if(command==='create')await multiplayer.create($('#friend-name').value,$('#friend-faction').value,crypto.getRandomValues(new Uint32Array(1))[0]);
   if(command==='join')await multiplayer.join($('#friend-code').value.trim(),$('#friend-name').value,$('#friend-faction').value);
   if(command==='resume'){if(!await multiplayer.resume())throw Error('No saved room could be resumed on this device. Join a room to get started.');}
   if(command==='start')await multiplayer.start();
   if(command==='copy'){try{if(globalThis.PREGENESIS_NATIVE?.copyText)await globalThis.PREGENESIS_NATIVE.copyText(multiplayer.inviteURL());else await navigator.clipboard.writeText(multiplayer.inviteURL());toast('Invite link copied.');}catch{toast('Copy the invite address shown in the room.');}}
   if(command==='return')closeModal();
   if(command==='leave'){await multiplayer.leave();$('#welcome').hidden=false;$('#game').inert=true;renderRoomBar();showFriends();}
  }catch(error){const target=$('#friend-error');if(target)target.textContent=error.message;else toast(error.message);}finally{roomRequestPending=false;syncRoomControls();}
 });
 if(/^#room=[A-Z2-9]{8}$/.test(location.hash))setTimeout(showFriends,0);
}
function renderRoomBar(){
 const bar=$('#friend-room-bar');if(!multiplayer.connected||!multiplayer.snapshot){bar.hidden=true;return;}
 bar.hidden=false;bar.dataset.status=multiplayer.connectionStatus;const snap=multiplayer.snapshot,current=snap.room.players.find(p=>p.id===snap.room.activePlayerId);
 const status=multiplayer.busy?'Confirming your order…':multiplayer.connectionStatus!=='connected'?'Reconnecting… orders paused':snap.room.status==='waiting'?'Gathering players':snap.room.status==='finished'?'Campaign finished':multiplayer.myTurn?'Your turn':(current?.name||'Friend')+' is playing';
 const markup='<button data-friends>Room '+esc(snap.room.code)+'</button><span role="status">'+esc(status)+'</span>';
 if(bar.innerHTML!==markup){const focused=bar.contains(document.activeElement);bar.innerHTML=markup;bar.querySelector('button').onclick=showFriends;if(focused)bar.querySelector('button').focus({preventScroll:true});}
 $('#save-status').textContent=multiplayer.busy?'CONFIRMING…':multiplayer.connectionStatus!=='connected'?'RECONNECTING':'ROOM SAVED';
}
function showFriends(){
 const snap=multiplayer.snapshot;
 if(multiplayer.connected&&snap){const {room,you}=snap;modal(`<div class="eyebrow">PLAY WITH FRIENDS · ${room.players.length}/4</div><h2>${room.status==='waiting'?'Gather your realms':'Your campaign room'}</h2><div class="room-code">${esc(room.code)}</div><p class="friend-status">${room.status==='waiting'?'Share the invite, then start when everyone has joined. Unclaimed realms are controlled by the game.':'Players take turns. Cities, research and movement refresh after everyone finishes the round.'}</p><ul class="friend-seats">${room.players.map(p=>`<li>${crests[p.faction]}<span><strong>${esc(p.name)}</strong><small>${esc(factionMeta(p.faction).name)}</small></span><span class="seat-badge">${p.id===you.id?'YOU':p.id===room.hostId?'HOST':''}</span></li>`).join('')}</ul><p class="friend-invite">${esc(multiplayer.inviteURL())}</p><div class="friend-actions"><button class="action-button" data-room-action="copy">Copy invite</button>${room.status==='waiting'&&you.isHost?`<button class="action-button gold" data-room-action="start" ${room.players.length<2?'disabled':''}>Start campaign</button>`:room.status!=='waiting'?'<button class="action-button gold" data-room-action="return">Return to map</button>':''}<button class="text-button" data-room-action="leave">Leave room</button></div><p class="friend-error" id="friend-error" role="status"></p>`);$('#modal-body').dataset.roomPanel='true';syncRoomControls();return;}
 modal(`<div class="eyebrow">ONLINE MULTIPLAYER</div><h2>Play with friends</h2><p class="friend-status">Two to four players. One shared world. Create a room and send the invite.</p><div class="friend-form"><label>Your name<input id="friend-name" maxlength="32" autocomplete="nickname" placeholder="Choose a name"></label><label>Your realm<select id="friend-faction">${FACTIONS.map(f=>`<option value="${f.id}" ${f.id===chosenFaction?'selected':''}>${esc(f.patron)} · ${esc(f.name)}</option>`).join('')}</select></label><button class="primary action-button" data-room-action="create">Create a room</button><div class="friend-divider">OR JOIN FRIENDS</div><label>Room code<input id="friend-code" maxlength="8" autocapitalize="characters" autocomplete="off" spellcheck="false" placeholder="8-character code" value="${esc(/^#room=([A-Z2-9]{8})$/.exec(location.hash)?.[1]||'')}"></label><button class="action-button gold" data-room-action="join">Join room</button><button class="text-button" data-room-action="resume">Reconnect to saved room</button><p class="friend-error" id="friend-error" role="status"></p></div>`);$('#modal-body').dataset.roomPanel='true';syncRoomControls();
}

window.addEventListener('pre-genesis:before-update',event=>{
 if(multiplayer.busy||roomRequestPending){event.preventDefault();toast('Wait for the current room request to finish before updating.');return;}
 if(started&&!save()){event.preventDefault();toast('Export a save file before updating. Browser storage is unavailable.');}
});
